"""Trusted static markup; no runtime file content is interpreted as HTML."""

PAGE = b'<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Grobase status</title>\n<link rel="stylesheet" href="/status.css"></head>\n<body><main><h1>Grobase status</h1><h2 id="overall" aria-live="polite">Unknown</h2><p id="updated">Waiting for measurements</p><div id="components"></div><footer><small>Observed HTTP availability. Missing or stale measurements are unknown. Failed checks are observations, not confirmed incidents or contractual uptime.</small><p><a href="/status.json">Status data</a></p></footer></main>\n<script src="/status.js" defer></script></body></html>\n'

STYLESHEET = b':root{--bg:#f3f5f7;--fg:#172126;--line:#ced6db;--ok:#176345;--down:#a12733;--muted:#58646e}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:16px system-ui,sans-serif}main{max-width:880px;margin:64px auto;padding:0 24px}h1{font-size:36px}section{border-top:1px solid var(--line);padding:20px 0}.row{display:flex;justify-content:space-between;gap:24px;flex-wrap:wrap}.operational{color:var(--ok)}.down,.degraded{color:var(--down)}.unknown,p,small{color:var(--muted)}li{margin:6px 0}footer{margin-top:40px}a{color:var(--fg)}\n'

SCRIPT = b"function text(tag, value){const node=document.createElement(tag);node.textContent=value;return node}\nfunction date(seconds){return new Date(seconds*1000).toLocaleString()}\nasync function refresh(){\n  try{\n    const response=await fetch('/status.json',{cache:'no-store'});if(!response.ok)throw Error('unavailable');const data=await response.json();\n    const overall=document.getElementById('overall');overall.textContent=data.status;overall.className=data.status;\n    document.getElementById('updated').textContent='Updated '+date(data.generated_at);\n    const list=document.getElementById('components');list.replaceChildren();\n    for(const item of data.components){\n      const section=document.createElement('section'),row=document.createElement('div');row.className='row';row.append(text('strong',item.name));\n      const state=text('span',item.status);state.className=item.status;row.append(state);section.append(row);\n      section.append(text('p',item.last_checked?'Last checked '+date(item.last_checked)+' \xc2\xb7 '+item.successful_samples+'/'+item.sample_count+' successful samples':'No measurements'));\n      if(item.failed_checks.length){const details=document.createElement('details');details.append(text('summary','Recent failed checks'));const failures=document.createElement('ul');for(const at of item.failed_checks)failures.append(text('li',date(at)));details.append(failures);section.append(details)}\n      list.append(section);\n    }\n  }catch{document.getElementById('overall').textContent='Unknown';document.getElementById('overall').className='unknown';document.getElementById('updated').textContent='Measurements unavailable';document.getElementById('components').replaceChildren()}\n}\nrefresh();setInterval(refresh,30000);\n"
